public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException(
                "index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                int codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
                if (codePoint <= 0x7F) {
                    size += 1;
                } else if (codePoint <= 0x7FF) {
                    size += 2;
                } else if (codePoint <= 0xFFFF) {
                    size += 3;
                } else {
                    size += 4;
                }
                i++; // skip low surrogate
                continue;
            }
            // Unmatched high surrogate: treat as 3 bytes (invalid UTF-8)
            size += 3;
        } else if (Character.isLowSurrogate(ch)) {
            // Unmatched low surrogate: treat as 3 bytes
            size += 3;
        } else {
            if (ch <= 0x7F) {
                size += 1;
            } else if (ch <= 0x7FF) {
                size += 2;
            } else {
                size += 3;
            }
        }
    }
    return size;
}

