public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    // Ensure we have enough space
    int required = size + byteLength;
    if (required > data.length) {
        int newCap = Math.max(data.length * 2, required);
        byte[] newData = new byte[newCap];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }
    if (byteArrayValue == null) {
        // Fill with null bytes (zeros)
        for (int i = 0; i < byteLength; i++) {
            data[size + i] = 0;
        }
    } else {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset and byteLength out of bounds");
        }
        System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
    }
    size += byteLength;
    return this;
}

