        prevTreeEdge.nextTreeEdge = nextTreeEdge;
    } else {
        // this edge was the first in the source node's list
        source.firstTreeEdge = nextTreeEdge;
    }
    if (nextTreeEdge != null) {
        nextTreeEdge.prevTreeEdge = prevTreeEdge;
    } else {
        // this edge was the last in the source node's list
        source.lastTreeEdge = prevTreeEdge;
    }

    // Remove this edge from the tree edge list of the target node
    if (prevTreeEdge2 != null) {
        prevTreeEdge2.nextTreeEdge2 = nextTreeEdge2;
    } else {
        // this edge was the first in the target node's list
        target.firstTreeEdge = nextTreeEdge2;
    }
    if (nextTreeEdge2 != null) {
        nextTreeEdge2.prevTreeEdge2 = prevTreeEdge2;
    } else {
        // this edge was the last in the target node's list
        target.lastTreeEdge = prevTreeEdge2;
