private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator positioned at the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // Traverse the outer face until we find a node satisfying the predicate
    // or until we reach the stop node.
    while (true) {
        Node current = circ.getNode();

        // If the current node satisfies the predicate, return the circulator.
        if (predicate.test(current)) {
            return circ;
        }

        // If we have reached the stop node, return the circulator pointing to it.
        if (current == stop) {
            return circ;
        }

        // Move to the next node in the specified direction.
        // Positive dir indicates forward traversal, negative indicates reverse.
        circ = (dir > 0) ? circ.next() : circ.prev();
    }
}

