private void check(String modelName) throws IllegalStateException {
    // Retrieve the list of sharding key indices for the given model.
    List<Integer> indices = shardingKeyIndices.get(modelName);
    if (indices == null || indices.isEmpty()) {
        // Nothing to check if there are no sharding keys defined.
        return;
    }

    // Ensure the indices are sorted to correctly detect gaps.
    indices.sort(Integer::compareTo);

    // Verify that each successive index is exactly one greater than the previous.
    for (int i = 1; i < indices.size(); i++) {
        int prev = indices.get(i - 1);
        int curr = indices.get(i);
        if (curr != prev + 1) {
            throw new IllegalStateException(
                "Sharding key indices for model '" + modelName + "' are not continuous: " + indices);
        }
    }
}

