private String unescapeId(String input) {
    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char ch = input.charAt(i);
        if (ch != '\\') {
            sb.append(ch);
            continue;
        }
        // Escape sequence
        if (i + 1 >= len) {
            // Trailing backslash, treat literally
            sb.append('\\');
            continue;
        }
        char next = input.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'a':
                sb.append('\u0007'); // alert
                i++;
                break;
            case 'v':
                sb.append('\u000B'); // vertical tab
                i++;
                break;
            case '0':
                sb.append('\0');
                i++;
                break;
            case 'x':
                // \xhh
                if (i + 3 < len) {
                    char h1 = input.charAt(i + 2);
                    char h2 = input.charAt(i + 3);
                    int val = hexToInt(h1) * 16 + hexToInt(h2);
                    if (val >= 0) {
                        sb.append((char) val);
                        i += 3;
                        break;
                    }
                }
                // Invalid, treat literally
                sb.append('\\').append('x');
                i++;
                break;
            case 'u':
                // \uhhhh
                if (i + 5 < len) {
                    int val = 0;
                    boolean ok = true;
                    for (int j = 0; j < 4; j++) {
                        char h = input.charAt(i + 2 + j);
                        int d = hexToInt(h);
                        if (d < 0) {
                            ok = false;
                            break;
                        }
                        val = (val << 4) | d;
                    }
                    if (ok) {
                        sb.append((char) val);
                        i += 5;
                        break;
                    }
                }
                sb.append('\\').append('u');
                i++;
                break;
            case 'U':
                // \Uhhhhhhhh
                if (i + 9 < len) {
                    int val = 0;
                    boolean ok = true;
                    for (int j = 0; j < 8; j++) {
                        char h = input.charAt(i + 2 + j);
                        int d = hexToInt(h);
                        if (d < 0) {
                            ok = false;
                            break;
                        }
                        val = (val << 4) | d;
                    }
                    if (ok) {
                        // Convert code point to chars
                        sb.appendCodePoint(val);
                        i += 9;
                        break;
                    }
                }
                sb.append('\\').append('U');
                i++;
                break;
            default:
                // Escape any other character
                sb.append(next);
                i++;
                break;
        }
    }
    return sb.toString();
}

private int hexToInt(char c) {
    if ('0' <= c && c <= '9') return c - '0';
    if ('a' <= c && c <= 'f') return 10 + (c - 'a');
    if ('A' <= c && c <= 'F') return 10 + (c - 'A');
    return -1;
}

