    // Unlink this bucket from its chain
    if (prev != null) {
        prev.next = next;
    } else if (table != null) {
        // This bucket is the head of the chain for its hash slot
        table.buckets[hash] = next;
    }
    if (next != null) {
        next.prev = prev;
