private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    if (prev == null) {
        first = next;
    } else {
        prev.next = next;
    }
    if (next == null) {
        last = prev;
    } else {
        next.prev = prev;
    }
    node.prev = null;
    node.next = null;
    size--;
    modCount++;
    return true;
}

