private String parseToken(final char[] terminators) {
    StringBuilder sb = new StringBuilder();
    while (pos < input.length()) {
        char c = input.charAt(pos);
        boolean isTerm = false;
        if (terminators != null) {
            for (char t : terminators) {
                if (c == t) {
                    isTerm = true;
                    break;
                }
            }
        }
        if (isTerm) {
            pos++; // consume the terminator
            break;
        }
        sb.append(c);
        pos++;
    }
    return sb.toString();
}

