private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    int[] suffixArr = new int[n];
    long total = 0;
    long suffixSum = 0;
    for (int i = n - 1; i >= 0; i--) {
        int val = bounds.get(i);
        total += val;
        suffixSum += val;
        suffixArr[i] = (int) suffixSum;
    }
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(suffixArr[i]);
    }
    return new Pair<>(suffix, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }
    // Clamp indices to valid range
    if (from < 0) {
        from = 0;
    }
    if (to >= arr.length) {
        to = arr.length - 1;
    }
    if (from >= to) {
        return;
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == this || list.size == 0) {
        return;
    }
    // Connect the last node of this list to the first node of the source list
    ListNodeImpl<E> thisLast = this.tail.prev;
    ListNodeImpl<E> listFirst = list.head.next;
    ListNodeImpl<E> listLast = list.tail.prev;

    thisLast.next = listFirst;
    listFirst.prev = thisLast;

    // Connect the last node of the source list to the tail sentinel of this list
    listLast.next = this.tail;
    this.tail.prev = listLast;

    // Update size
    this.size += list.size;

    // Reset the source list to empty
    list.head.next = list.tail;
    list.tail.prev = list.head;
    list.size = 0;
}

