public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type bound = bounds[0];
    if (bound instanceof Class) {
        return bound;
    }
    if (bound instanceof ParameterizedType) {
        return ((ParameterizedType) bound).getRawType();
    }
    if (bound instanceof TypeVariable) {
        // Recursively resolve the bound of the nested type variable
        return resolveBound((TypeVariable<?>) bound);
    }
    if (bound instanceof WildcardType) {
        WildcardType wt = (WildcardType) bound;
        Type[] upper = wt.getUpperBounds();
        if (upper != null && upper.length > 0) {
            return upper[0];
        }
    }
    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // A set with 0 or 1 vertex is trivially a clique
    if (vertices == null || vertices.size() <= 1) {
        return true;
    }
    // Check every unordered pair of distinct vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue;
            }
            // If the graph does not contain an edge between v1 and v2, it's not a clique
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    java.util.TreeSet<Integer> set = new java.util.TreeSet<>();
    for (K key : keys) {
        set.add((Integer) key);
    }
    java.util.List<Integer> result = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        Integer k = (Integer) key;
        Integer lower = set.lower(k);
        result.add(lower);
    }
    return result;
}

