private String buildContentRange() {
    // Build the 'Content-Range' header value in the form:
    //   "bytes <start>-<end>/<total>"
    // If the total size is unknown, use "*" as per RFC 7233.
    // It is assumed that the class has the following fields:
    //   long start, end, total;
    if (total < 0) {
        return "bytes " + start + "-" + end + "/*";
    }
    return "bytes " + start + "-" + end + "/" + total;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return Collections.emptyList();
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        while (true) {
            try {
                Object obj = ois.readObject();
                if (obj instanceof ThreadSnapshot) {
                    ThreadSnapshot ts = (ThreadSnapshot) obj;
                    long tsTime = ts.getTimestamp();
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (tsTime >= range.getStartTime() && tsTime <= range.getEndTime()) {
                            result.add(ts);
                            break;
                        }
                    }
                }
            } catch (EOFException eof) {
                break;
            } catch (ClassNotFoundException cnf) {
                throw new IOException("Failed to deserialize ThreadSnapshot", cnf);
            }
        }
    }
    return result;
}
